#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

// Greedy Coin Change (works for standard denominations)
int minCoins(vector<int>& coins, int amount) {
    // Sort coins in descending order
    sort(coins.begin(), coins.end(), greater<int>());
    int count = 0;

    for(int coin : coins) {
        while(amount >= coin) {
            amount -= coin;
            count++;
        }
    }
    return (amount == 0) ? count : -1;
}

int main() {
    vector<int> coins = {1, 5, 10, 25};
    int amount = 63;
    cout << "Minimum coins for " << amount << ": ";
    cout << minCoins(coins, amount) << endl;
    // Output: 6 (25+25+10+1+1+1)
    return 0;
}

