import java.util.*;

public class HuffmanCoding {
    static class Node implements Comparable<Node> {
        char ch;
        int freq;
        Node left, right;
        Node(char ch, int freq) { this.ch = ch; this.freq = freq; }
        public int compareTo(Node o) { return this.freq - o.freq; }
    }

    static void generateCodes(Node root, String code, Map<Character, String> codes) {
        if (root == null) return;
        if (root.left == null && root.right == null) {
            codes.put(root.ch, code.isEmpty() ? "0" : code);
            return;
        }
        generateCodes(root.left, code + "0", codes);
        generateCodes(root.right, code + "1", codes);
    }

    public static void main(String[] args) {
        String text = "aabbbccccdddddd";
        Map<Character, Integer> freq = new HashMap<>();
        for (char c : text.toCharArray()) freq.merge(c, 1, Integer::sum);

        PriorityQueue<Node> pq = new PriorityQueue<>();
        for (var e : freq.entrySet()) pq.add(new Node(e.getKey(), e.getValue()));

        while (pq.size() > 1) {
            Node left = pq.poll(), right = pq.poll();
            Node parent = new Node('\0', left.freq + right.freq);
            parent.left = left; parent.right = right;
            pq.add(parent);
        }

        Map<Character, String> codes = new HashMap<>();
        generateCodes(pq.peek(), "", codes);
        codes.forEach((k, v) -> System.out.println(k + ": " + v));
    }
}

