#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct Node {
    char ch;
    int freq;
    struct Node *left, *right;
} Node;

typedef struct { Node* data[256]; int size; } MinHeap;

Node* newNode(char ch, int freq) {
    Node* n = (Node*)malloc(sizeof(Node));
    n->ch = ch; n->freq = freq;
    n->left = n->right = NULL;
    return n;
}

void swap(Node** a, Node** b) { Node* t = *a; *a = *b; *b = t; }

void heapifyUp(MinHeap* h, int i) {
    while (i > 0 && h->data[(i-1)/2]->freq > h->data[i]->freq) {
        swap(&h->data[(i-1)/2], &h->data[i]);
        i = (i-1)/2;
    }
}

void heapifyDown(MinHeap* h, int i) {
    int smallest = i, l = 2*i+1, r = 2*i+2;
    if (l < h->size && h->data[l]->freq < h->data[smallest]->freq) smallest = l;
    if (r < h->size && h->data[r]->freq < h->data[smallest]->freq) smallest = r;
    if (smallest != i) { swap(&h->data[i], &h->data[smallest]); heapifyDown(h, smallest); }
}

void insert(MinHeap* h, Node* n) { h->data[h->size] = n; heapifyUp(h, h->size++); }
Node* extractMin(MinHeap* h) { Node* min = h->data[0]; h->data[0] = h->data[--h->size]; heapifyDown(h, 0); return min; }

void printCodes(Node* root, char code[], int top) {
    if (root->left) { code[top] = '0'; printCodes(root->left, code, top+1); }
    if (root->right) { code[top] = '1'; printCodes(root->right, code, top+1); }
    if (!root->left && !root->right) { code[top] = '\0'; printf("%c: %s\n", root->ch, code); }
}

int main() {
    char chars[] = {'a','b','c','d'};
    int freqs[] = {2, 3, 4, 6};
    int n = 4;
    MinHeap h = {.size = 0};
    for (int i = 0; i < n; i++) insert(&h, newNode(chars[i], freqs[i]));
    while (h.size > 1) {
        Node *l = extractMin(&h), *r = extractMin(&h);
        Node *p = newNode('\0', l->freq + r->freq);
        p->left = l; p->right = r;
        insert(&h, p);
    }
    char code[100];
    printCodes(h.data[0], code, 0);
    return 0;
}

