#include <iostream>
#include <vector>
#include <algorithm>
#include <queue>
using namespace std;

// ---- KRUSKAL'S ALGORITHM ----
class DSU {
public:
    vector<int> parent, rank_;
    DSU(int n) : parent(n), rank_(n, 0) {
        for (int i = 0; i < n; i++) parent[i] = i;
    }
    int find(int x) {
        if (parent[x] != x) parent[x] = find(parent[x]);
        return parent[x];
    }
    bool unite(int x, int y) {
        int px = find(x), py = find(y);
        if (px == py) return false;
        if (rank_[px] < rank_[py]) swap(px, py);
        parent[py] = px;
        if (rank_[px] == rank_[py]) rank_[px]++;
        return true;
    }
};

int kruskal(int V, vector<tuple<int,int,int>>& edges) {
    sort(edges.begin(), edges.end());
    DSU dsu(V);
    int mstWeight = 0, edgesUsed = 0;

    for (auto& [w, u, v] : edges) {
        if (dsu.unite(u, v)) {
            mstWeight += w;
            cout << u << " - " << v << " : " << w << endl;
            if (++edgesUsed == V - 1) break;
        }
    }
    return mstWeight;
}

// ---- PRIM'S ALGORITHM ----
int prim(int V, vector<vector<pair<int,int>>>& adj) {
    vector<bool> inMST(V, false);
    priority_queue<pair<int,int>, vector<pair<int,int>>, greater<>> pq;
    pq.push({0, 0}); // {weight, vertex}
    int mstWeight = 0;

    while (!pq.empty()) {
        auto [w, u] = pq.top(); pq.pop();
        if (inMST[u]) continue;
        inMST[u] = true;
        mstWeight += w;

        for (auto& [v, wt] : adj[u]) {
            if (!inMST[v]) pq.push({wt, v});
        }
    }
    return mstWeight;
}

int main() {
    int V = 5;
    // Kruskal's: edges as {weight, u, v}
    vector<tuple<int,int,int>> edges = {
        {2,0,1}, {3,0,3}, {6,1,2}, {8,1,3},
        {5,1,4}, {7,2,4}, {9,3,4}
    };
    cout << "Kruskal's MST:" << endl;
    cout << "Total weight: " << kruskal(V, edges) << endl;

    // Prim's: adjacency list
    vector<vector<pair<int,int>>> adj(V);
    for (auto& [w, u, v] : edges) {
        adj[u].push_back({v, w});
        adj[v].push_back({u, w});
    }
    cout << "\nPrim's MST weight: " << prim(V, adj) << endl;
    return 0;
}

