import java.util.*;

public class MST {
    static int[] parent, rank;

    static int find(int x) {
        if (parent[x] != x) parent[x] = find(parent[x]);
        return parent[x];
    }

    static boolean union(int x, int y) {
        int px = find(x), py = find(y);
        if (px == py) return false;
        if (rank[px] < rank[py]) { int t = px; px = py; py = t; }
        parent[py] = px;
        if (rank[px] == rank[py]) rank[px]++;
        return true;
    }

    // Kruskal's Algorithm
    static int kruskal(int V, int[][] edges) {
        Arrays.sort(edges, (a, b) -> a[2] - b[2]);
        parent = new int[V]; rank = new int[V];
        for (int i = 0; i < V; i++) parent[i] = i;

        int mstWeight = 0, count = 0;
        for (int[] e : edges) {
            if (union(e[0], e[1])) {
                mstWeight += e[2];
                if (++count == V - 1) break;
            }
        }
        return mstWeight;
    }

    // Prim's Algorithm
    static int prim(int V, List<int[]>[] adj) {
        boolean[] inMST = new boolean[V];
        PriorityQueue<int[]> pq = new PriorityQueue<>((a, b) -> a[1] - b[1]);
        pq.offer(new int[]{0, 0});
        int mstWeight = 0;

        while (!pq.isEmpty()) {
            int[] top = pq.poll();
            if (inMST[top[0]]) continue;
            inMST[top[0]] = true;
            mstWeight += top[1];
            for (int[] next : adj[top[0]]) {
                if (!inMST[next[0]]) pq.offer(new int[]{next[0], next[1]});
            }
        }
        return mstWeight;
    }

    public static void main(String[] args) {
        int V = 5;
        int[][] edges = {{0,1,2},{0,3,3},{1,2,6},{1,3,8},{1,4,5},{2,4,7},{3,4,9}};
        System.out.println("Kruskal's MST: " + kruskal(V, edges));
    }
}

