int parent[100], rnk[100];

int find(int x) {
    if (parent[x] != x) parent[x] = find(parent[x]);
    return parent[x];
}

int unite(int x, int y) {
    int px = find(x), py = find(y);
    if (px == py) return 0;
    if (rnk[px] < rnk[py]) { int t = px; px = py; py = t; }
    parent[py] = px;
    if (rnk[px] == rnk[py]) rnk[px]++;
    return 1;
}

typedef struct { int u, v, w; } Edge;

int cmp(const void *a, const void *b) {
    return ((Edge*)a)->w - ((Edge*)b)->w;
}

int main() {
    int V = 5;
    Edge edges[] = {{0,1,2},{0,3,3},{1,2,6},{1,3,8},{1,4,5},{2,4,7},{3,4,9}};
    int E = 7;

    for (int i = 0; i < V; i++) { parent[i] = i; rnk[i] = 0; }
    qsort(edges, E, sizeof(Edge), cmp);

    int mstWeight = 0, count = 0;
    for (int i = 0; i < E && count < V - 1; i++) {
        if (unite(edges[i].u, edges[i].v)) {
            mstWeight += edges[i].w;
            printf("%d - %d: %d\n", edges[i].u, edges[i].v, edges[i].w);
            count++;
        }
    }
    printf("MST weight: %d\n", mstWeight);
    return 0;
}
